private CommandLineParser buildParserWithHandler(Set<Option> handler) {
    return DefaultParser.builder()
            .setDeprecatedHandler(handler::add)
            .build();
}

@Test
public void testDeprecatedHandlerTriggersForDeprecatedOptions() {
    Set<Option> handler = new HashSet<>();
    parser = buildParserWithHandler(handler);

    Option opt1 = Option.builder().option("d1").deprecated().build();
    Option opt2 = Option.builder().option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();
    Option opt3 = Option.builder().option("a").build();

    CommandLine cl = assertDoesNotThrow(() -> parser.parse(
            new Options()
                    .addOption(opt1)
                    .addOption(opt2)
                    .addOption(opt3),
            new String[]{"-d1", "-d2", "-a"}),
            "Parsing should not throw an exception");

    assertTrue(cl.hasOption(opt1.getOpt()), "Parsed command line should contain option d1");
    assertTrue(cl.hasOption(opt2.getOpt()), "Parsed command line should contain option d2");
    assertTrue(cl.hasOption(opt3.getOpt()), "Parsed command line should contain option a");

    assertTrue(handler.contains(opt1), "Handler should be invoked for deprecated option d1");
    assertTrue(handler.contains(opt2), "Handler should be invoked for deprecated option d2");
}

@Test
public void testDeprecatedHandlerDoesNotTriggerForNonDeprecatedOption() {
    Set<Option> handler = new HashSet<>();
    parser = buildParserWithHandler(handler);

    Option opt1 = Option.builder().option("d1").deprecated().build();
    Option opt2 = Option.builder().option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();
    Option opt3 = Option.builder().option("a").build();

    CommandLine cl = assertDoesNotThrow(() -> parser.parse(
            new Options()
                    .addOption(opt1)
                    .addOption(opt2)
                    .addOption(opt3),
            new String[]{"-d1", "-d2", "-a"}),
            "Parsing should not throw an exception");

    assertFalse(handler.contains(opt3), "Handler should not be invoked for non‑deprecated option a");
}

