 * Verifies that the original {@link Gson} instance remains unchanged after builder
 * modifications.
 */
@Test
public void testDefaultGsonNewBuilderModification_DefaultGsonUnchanged() {
  setupTestDefaultGsonNewBuilderModification();
  assertDefaultGson(gson);
}

