 * does not inherit the custom adapters.
 */
@Test
public void testDefaultGsonNewBuilderModification_NewBuilderFromOriginalIsDefault() {
  setupTestDefaultGsonNewBuilderModification();
  assertDefaultGson(gson.newBuilder().create());
}

