  jsonWriter.value(Math.PI);
  jsonWriter.value(Math.E);
  jsonWriter.endArray();
  jsonWriter.close();
  assertThat(stringWriter.toString())
      .isEqualTo(
          "[-0.0,"
              + "1.0,"
              + "1.7976931348623157E308,"
              + "4.9E-324,"
              + "0.0,"
              + "-0.5,"
              + "2.2250738585072014E-308,"
              + "3.141592653589793,"
              + "2.718281828459045]");
}

