// Helper method to write a single double value into a JSON array and return the JSON string.
private String writeSingleDouble(double value) throws IOException {
  StringWriter stringWriter = new StringWriter();
  JsonWriter jsonWriter = new JsonWriter(stringWriter);
  jsonWriter.beginArray();
  jsonWriter.value(value);
  jsonWriter.endArray();
  jsonWriter.close();
  return stringWriter.toString();
}

