                 systemDoc, htmlOutput(systemDoc));
    assertEquals("XML output should preserve the system DOCTYPE declaration",
                 systemDoc, xmlOutput(systemDoc));

    String legacyDoc = "<!DOCTYPE html SYSTEM \"about:legacy-compat\">";
    assertEquals("HTML output should preserve the legacy system DOCTYPE declaration",
                 legacyDoc, htmlOutput(legacyDoc));
    assertEquals("XML output should preserve the legacy system DOCTYPE declaration",
                 legacyDoc, xmlOutput(legacyDoc));
}

