@Test public void handlesAbsPrefixOnHasAttr() {
    // 1: no abs url; 2: has abs url
    Document doc = Jsoup.parse("<a id=1 href='/foo'>One</a> <a id=2 href='https://jsoup.org/'>Two</a>");
    Element one = doc.select("#1").first();
