private static final int EXPECTED_VISIBLE_ATTRIBUTES = 2;

/* Helper to create the Attributes instance used in all tests */
private Attributes createAttributes() {
    Attributes a = new Attributes();
    a.put("One", "One");
    a.put(Attributes.internalKey("baseUri"), "example.com");
    a.put("Two", "Two");
    a.put(Attributes.internalKey("another"), "example.com");
    return a;
}

/* Helper to count visible (non‑internal) attributes */
private int countVisibleAttributes(Attributes attrs) {
    int count = 0;
    for (Attribute attribute : attrs) {
        count++;
    }
    return count;
}

/* 1. Verify that the iterator reports a next element before the first visible attribute */
@Test
void testIteratorSkipsInternal_hasNextBeforeFirst() {
    Attributes a = createAttributes();
    Iterator<Attribute> it = a.iterator();
    assertTrue(it.hasNext(), "Iterator should have a next element before the first visible attribute");
}

/* 2. Verify the key of the first visible attribute */
@Test
void testIteratorSkipsInternal_firstKey() {
    Attributes a = createAttributes();
    Iterator<Attribute> it = a.iterator();
    // Directly retrieve the first element; if none exists the test will fail with an exception
    Attribute attr = it.next();
    assertEquals("One", attr.getKey(), "First visible attribute key should be 'One'");
}

/* 3. Verify that the iterator reports a next element before the second visible attribute */
@Test
void testIteratorSkipsInternal_hasNextBeforeSecond() {
    Attributes a = createAttributes();
    Iterator<Attribute> it = a.iterator();
    it.next(); // skip first visible attribute
    assertTrue(it.hasNext(), "Iterator should have a next element before the second visible attribute");
}

/* 4. Verify the key of the second visible attribute */
@Test
void testIteratorSkipsInternal_secondKey() {
    Attributes a = createAttributes();
    Iterator<Attribute> it = a.iterator();
    it.next(); // first visible attribute
    Attribute attr = it.next(); // second visible attribute
    assertEquals("Two", attr.getKey(), "Second visible attribute key should be 'Two'");
}

/* 5. Verify that the iterator has no more elements after the second visible attribute */
@Test
void testIteratorSkipsInternal_noMoreElements() {
    Attributes a = createAttributes();
    Iterator<Attribute> it = a.iterator();
    it.next(); // first visible attribute
    it.next(); // second visible attribute
    assertFalse(it.hasNext(), "Iterator should have no more elements after the second visible attribute");
}

/* 6. Verify the total number of visible attributes returned by the iterator */
@Test
void testIteratorSkipsInternal_visibleCount() {
    Attributes a = createAttributes();
    int seen = countVisibleAttributes(a);
    assertEquals(EXPECTED_VISIBLE_ATTRIBUTES, seen,
            "Number of visible attributes returned by the iterator should match the expected count");
}

