@Test public void testClassDomMethods() {
    Document doc = Jsoup.parse("<div><span class=' mellow yellow '>Hello <b>Yellow</b></span></div>");
    List<Element> els = doc.getElementsByAttribute("class");
    Element span = els.get(0);
    assertEquals("mellow yellow", span.className());
    assertTrue(span.hasClass("mellow"));
    assertTrue(span.hasClass("yellow"));
    Set<String> classes = span.classNames();
    assertEquals(2, classes.size());
    assertTrue(classes.contains("mellow"));
    assertTrue(classes.contains("yellow"));

    assertEquals("", doc.className());
    classes = doc.classNames();
    assertEquals(0, classes.size());
    assertFalse(doc.hasClass("mellow"));
}

proposals.refactored:
private static final int EXPECTED_SPAN_CLASS_COUNT = 2;
private static final int EXPECTED_EMPTY_CLASS_COUNT = 0;

private Document createTestDocument() {
    return Jsoup.parse("<div><span class=' mellow yellow '>Hello <b>Yellow</b></span></div>");
}

private Element getSpanElement(Document doc) {
    List<Element> els = doc.getElementsByAttribute("class");
    return els.get(0);
}

@Test
public void testClassDomMethods_ElementClass() {
    Document doc = createTestDocument();
    Element span = getSpanElement(doc);

    assertEquals("Span should have class name 'mellow yellow'", "mellow yellow", span.className());
    assertTrue("Span should contain class 'mellow'", span.hasClass("mellow"));
    assertTrue("Span should contain class 'yellow'", span.hasClass("yellow"));

    Set<String> classes = span.classNames();
    assertEquals("Span should have exactly " + EXPECTED_SPAN_CLASS_COUNT + " classes", 
                 EXPECTED_SPAN_CLASS_COUNT, classes.size());
    assertTrue("Span classes should contain 'mellow'", classes.contains("mellow"));
    assertTrue("Span classes should contain 'yellow'", classes.contains("yellow"));
}

@Test
public void testClassDomMethods_DocumentClass() {
    Document doc = createTestDocument();

    assertEquals("Document should have no class name", "", doc.className());

    Set<String> classes = doc.classNames();
    assertEquals("Document should have exactly " + EXPECTED_EMPTY_CLASS_COUNT + " classes", 
                 EXPECTED_EMPTY_CLASS_COUNT, classes.size());
    assertFalse("Document should not have class 'mellow'", doc.hasClass("mellow"));
}

