@Test
void testHasTextWhenIterating_allTextNodesNotBlank() {
    List<TextNode> textNodes = getAllTextNodes();
    assertAll("All TextNodes should contain non‑blank text",
            textNodes.stream()
                    .map(tn -> (Executable) () -> assertFalse(
                            StringUtil.isBlank(tn.text()),
                            "TextNode text should not be blank: '" + tn.text() + "'"))
                    .collect(Collectors.toList()));
}

@EnabledIf("hasAtLeastOneTextNode")
@Test
void testHasTextWhenIterating_firstTextNodeContent() {
    TextNode first = getAllTextNodes().get(0);
    assertEquals("One ", first.text(),
            "First TextNode text should be exactly 'One '");
    assertEquals("One ", first.getWholeText(),
            "First TextNode whole text should be exactly 'One '");
}

/**
 * Parses the sample HTML and returns all TextNode instances found.
 */
private List<TextNode> getAllTextNodes() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    return doc.getAllElements().stream()
            .flatMap(el -> el.childNodes().stream())
            .filter(node -> node instanceof TextNode)
            .map(node -> (TextNode) node)
            .collect(Collectors.toList());
}

/**
 * Condition used by {@link EnabledIf} to enable {@code testHasTextWhenIterating_firstTextNodeContent}
 * only when the parsed document contains at least one TextNode.
 */
private static boolean hasAtLeastOneTextNode() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    return doc.getAllElements().stream()
            .flatMap(el -> el.childNodes().stream())
            .anyMatch(node -> node instanceof TextNode);
}

