private Document setupOwnerDocument() {
    return Jsoup.parse("<p>Hello");
}

private Element getFirstParagraph(Document doc) {
    return doc.select("p").first();
}

@Test
public void ownerDocument_elementOwnerDocument() {
    Document doc = setupOwnerDocument();
    Element p = getFirstParagraph(doc);
    assertTrue("Element's ownerDocument should be the same Document instance", p.ownerDocument() == doc);
}

@Test
public void ownerDocument_documentOwnerDocument() {
    Document doc = setupOwnerDocument();
    assertTrue("Document's ownerDocument should be itself", doc.ownerDocument() == doc);
}

@Test
public void ownerDocument_documentParentIsNull() {
    Document doc = setupOwnerDocument();
    assertNull("Document's parent should be null", doc.parent());
}

